using Microsoft.EntityFrameworkCore;using MyDoc.Data;using MyDoc.Models;namespace MyDoc.Services;public enum DocumentAccess{None,Viewer,Editor,Owner}public interface IDocumentAuthorizationService{Task<DocumentAccess>GetAccessAsync(int documentId,int userId,CancellationToken ct=default);}public sealed class DocumentAuthorizationService(DocSpaceDbContext db):IDocumentAuthorizationService{public async Task<DocumentAccess>GetAccessAsync(int documentId,int userId,CancellationToken ct=default){var doc=await db.Documents.AsNoTracking().FirstOrDefaultAsync(d=>d.Id==documentId,ct);if(doc is null)return DocumentAccess.None;if(doc.OwnerId==userId)return DocumentAccess.Owner;var share=await db.DocumentShares.AsNoTracking().FirstOrDefaultAsync(s=>s.DocumentId==documentId&&s.UserId==userId,ct);return share?.Permission==SharePermission.Editor?DocumentAccess.Editor:share is not null?DocumentAccess.Viewer:DocumentAccess.None;}}
